from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def bfs(start, goal):
        visited = set()
        queue = deque([(start, [start])])
        visited.add(start)

        while queue:
            (r, c), path = queue.popleft()

            if (r, c) == goal:
                return path

            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))

        return []

    path1 = bfs(start, goal)
    if path1:
        return path1

    path2 = bfs(goal, start)
    if path2:
        return path2[::-1]

    # Try to find a meeting point
    visited1 = set()
    queue1 = deque([start])
    visited1.add(start)
    path1_map = {start: [start]}

    while queue1:
        r, c = queue1.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited1:
                visited1.add((nr, nc))
                path1_map[(nr, nc)] = path1_map[(r, c)] + [(nr, nc)]
                queue1.append((nr, nc))

    visited2 = set()
    queue2 = deque([goal])
    visited2.add(goal)
    path2_map = {goal: [goal]}

    while queue2:
        r, c = queue2.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited2:
                visited2.add((nr, nc))
                path2_map[(nr, nc)] = path2_map[(r, c)] + [(nr, nc)]
                queue2.append((nr, nc))

    # Find intersection
    for cell in visited1:
        if cell in visited2:
            path1 = path1_map[cell]
            path2 = path2_map[cell][::-1]
            return path1 + path2[1:]

    return []
```

