def solve(n, edges, s, t):
    from collections import defaultdict

    if s == t:
        return 0

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize shortest distances with infinity
    import sys
    INF = sys.maxsize
    dist = [INF] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == INF:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != INF else -1
```

