def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize earliest times
    earliest = [float('inf')] * n
    earliest[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if earliest[u] + w < earliest[v]:
                earliest[v] = earliest[u] + w
                updated = True
        if not updated:
            break

    return earliest[t] if earliest[t] != float('inf') else -1
```

