def solve(n, edges, s, t):
    # Initialize earliest times with infinity
    earliest = [float('inf')] * n
    earliest[s] = 0  # Starting node has earliest time 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if earliest[u] + w < earliest[v]:
                earliest[v] = earliest[u] + w
                updated = True
        if not updated:
            break  # No more updates, shortest path found

    # Check if t is reachable
    if earliest[t] == float('inf'):
        return -1
    else:
        return earliest[t]
```

