def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize shortest path distances
    dist = [float('inf')] * n
    dist[s] = 0

    # Use BFS-like approach to relax edges until no more improvements can be made
    # This is similar to the Bellman-Ford algorithm
    for _ in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != float('inf') else -1
```

